.health-fill.low { background: var(--red); }
.stance { margin: 6px 0 0; font-size: 11px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--muted); text-shadow: 0 1px 2px #000; }

.weapon { position: absolute; right: 26px; bottom: 22px; text-align: right; text-shadow: 0 1px 3px #000; }
.weapon-name { margin: 0; font-size: 12px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--muted); }
.ammo { margin: 0; font-size: 34px; font-weight: 600; line-height: 1.1; }
.ammo span { font-size: 18px; color: var(--muted); margin-left: 6px; }
.ammo.low b { color: var(--red); }
.grenades { margin: 2px 0 0; font-size: 12px; color: var(--muted); letter-spacing: 0.08em; }

.debug {
  position: absolute; right: 8px; top: 8px; margin: 0; padding: 6px 8px;
  font: 11px/1.35 ui-monospace, monospace; color: #cfe; background: rgba(0, 0, 0, 0.55);
}

