toolUseResult.content:
/* Hedgerow — screens and HUD. Space Grotesk (site font, OFL) for the
   interface, the system's typewriter face for orders and briefings. */
@font-face {
  font-family: 'Space Grotesk';
  src: url('/assets/fonts/space-grotesk-latin.woff2') format('woff2');
  font-weight: 300 700;
  font-display: swap;
}

:root {
  --ink: #e8e4d8;
  --muted: #a39d8c;
  --dim: #6d685c;
  --line: rgba(232, 228, 216, 0.16);
  --line-strong: rgba(232, 228, 216, 0.34);
  --glass: rgba(14, 15, 13, 0.72);
  --glass-deep: rgba(9, 10, 9, 0.86);
  --brass: #d6a54a;
  --brass-soft: rgba(214, 165, 74, 0.16);
  --red: #e0442f;
  --green: #9fc46a;
  --night: #0b0d10;
  --type: 'American Typewriter', 'Courier Prime', 'Courier New', ui-monospace, monospace;
  color-scheme: dark;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--night);
  color: var(--ink);
  font-family: 'Space Grotesk', system-ui, sans-serif;
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}

#stage {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  display: block;
}
body.playing, body.playing #stage { cursor: none; }

.fade {
  position: fixed; inset: 0; background: #000; opacity: 0; pointer-events: none;
  transition: opacity 0.7s ease; z-index: 30;
}
.fade.on { opacity: 1; }

/* ---------- screens ---------- */

.screen {
  position: fixed; inset: 0; z-index: 40;
  display: none; align-items: center; justify-content: center;
  padding: 24px 16px;
  background: radial-gradient(ellipse at 50% 40%, rgba(10, 12, 14, 0.35), rgba(5, 6, 7, 0.86));
  overflow-y: auto;
}
.screen.on { display: flex; }
.screen[data-screen="start"] { background: radial-gradient(ellipse at 50% 35%, rgba(18, 22, 26, 0.2), rgba(4, 5, 6, 0.92)); }

.panel {
  width: min(560px, 100%);
  padding: 32px 32px 28px;
  background: var(--glass);
  border: 1px solid var(--line);
  border-radius: 4px;
  backdrop-filter: blur(6px);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.5);
}
.title-panel { text-align: center; background: transparent; border: none; box-shadow: none; backdrop-filter: none; }

.eyebrow {
  margin: 0 0 6px;
  font-size: 12px; letter-spacing: 0.28em; text-transform: uppercase; color: var(--brass);
}
.wordmark {
  margin: 0;
  font-size: clamp(44px, 10vw, 92px); font-weight: 700; letter-spacing: 0.16em;
  color: var(--ink);
  text-shadow: 0 4px 30px rgba(0, 0, 0, 0.8);
}
.subtitle { margin: 4px 0 28px; font-family: var(--type); font-size: 18px; color: var(--muted); }
h2 { margin: 0 0 14px; font-size: 28px; font-weight: 600; letter-spacing: 0.02em; }

.loading { width: min(320px, 100%); margin: 0 auto; }
.loading-track { height: 3px; background: var(--line); overflow: hidden; }
.loading-fill { display: block; height: 100%; width: 0; background: var(--brass); transition: width 0.2s ease; }
.loading-label { margin: 10px 0 0; font-size: 13px; color: var(--muted); letter-spacing: 0.06em; }
.error p { color: var(--red); }

.menu { display: flex; flex-direction: column; gap: 8px; align-items: stretch; width: min(320px, 100%); margin: 0 auto; }
.panel .menu { margin: 18px 0 0; width: 100%; }
.menu-item {
  display: block; width: 100%;
  padding: 12px 18px;
  font: inherit; font-size: 15px; letter-spacing: 0.08em; text-transform: uppercase; text-decoration: none; text-align: center;
  color: var(--ink);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line-strong);
  border-radius: 3px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}
.menu-item:hover, .menu-item:focus-visible { background: var(--brass-soft); border-color: var(--brass); outline: none; }
.menu-item.primary { background: var(--brass); border-color: var(--brass); color: #16130c; font-weight: 600; }
.menu-item.primary:hover, .menu-item.primary:focus-visible { background: #e8b95c; }
.ghost { font: inherit; color: var(--ink); background: none; border: 1px solid var(--line-strong); padding: 8px 14px; cursor: pointer; }
.row { display: flex; gap: 10px; margin-top: 20px; }
.row .menu-item { flex: 1; }
.best { margin-top: 18px; font-size: 13px; color: var(--muted); }

.briefing { width: min(640px, 100%); }
.when { margin: -6px 0 16px; font-family: var(--type); color: var(--muted); }
.briefing-text p { margin: 0 0 12px; font-family: var(--type); font-size: 15px; line-height: 1.55; color: #d8d2c2; }
.briefing-goals { margin: 14px 0 0; padding: 0 0 0 18px; font-size: 14px; line-height: 1.7; color: var(--ink); }
.briefing-goals li::marker { color: var(--brass); }
.hint { margin: 14px 0 0; font-size: 12px; color: var(--dim); text-align: center; }

.keys { display: grid; grid-template-columns: max-content 1fr; gap: 6px 18px; margin: 0 0 20px; font-size: 14px; }
.keys dt { color: var(--brass); font-weight: 600; }
.keys dd { margin: 0; color: var(--ink); }

.setting { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin: 0 0 14px; font-size: 14px; }
.setting input[type="range"] { width: 55%; accent-color: var(--brass); }
.setting select { font: inherit; color: var(--ink); background: #1b1c19; border: 1px solid var(--line-strong); padding: 4px 8px; }

.stats { display: grid; grid-template-columns: 1fr max-content; gap: 6px 18px; margin: 4px 0 6px; font-size: 15px; }
.stats dt { color: var(--muted); }
.stats dd { margin: 0; text-align: right; }
.stats .score { font-size: 20px; color: var(--brass); font-weight: 700; }
.objective-recap { font-family: var(--type); color: var(--muted); }

/* ---------- HUD ---------- */

.hud { position: fixed; inset: 0; pointer-events: none; z-index: 10; user-select: none; }

.crosshair, .hitmark { position: absolute; left: 50%; top: 50%; width: 0; height: 0; }
.crosshair i, .hitmark i { position: absolute; display: block; background: rgba(240, 236, 226, 0.85); box-shadow: 0 0 2px rgba(0, 0, 0, 0.9); }
.crosshair i { width: 2px; height: 8px; }
.crosshair i:nth-child(1) { left: -1px; top: calc(-8px - var(--spread, 8px)); }
.crosshair i:nth-child(2) { left: -1px; top: var(--spread, 8px); }
.crosshair i:nth-child(3) { width: 8px; height: 2px; top: -1px; left: calc(-8px - var(--spread, 8px)); }
.crosshair i:nth-child(4) { width: 8px; height: 2px; top: -1px; left: var(--spread, 8px); }
.crosshair.dot::after { content: ''; position: absolute; left: -1px; top: -1px; width: 2px; height: 2px; background: rgba(240, 236, 226, 0.9); }
.crosshair.hidden { opacity: 0; }

.hitmark { opacity: 0; transition: opacity 0.12s ease; }
.hitmark.on { opacity: 1; transition: none; }
.hitmark.kill i { background: var(--red); }
.hitmark i { width: 2px; height: 9px; }
.hitmark i:nth-child(1) { transform: translate(-7px, -14px) rotate(-45deg); }
.hitmark i:nth-child(2) { transform: translate(6px, -14px) rotate(45deg); }
.hitmark i:nth-child(3) { transform: translate(-7px, 5px) rotate(45deg); }
.hitmark i:nth-child(4) { transform: translate(6px, 5px) rotate(-45deg); }

.damage { position: absolute; left: 50%; top: 50%; width: 0; height: 0; }
.damage i {
  position: absolute; left: -60px; top: -160px; width: 120px; height: 40px;
  border-top: 5px solid rgba(224, 68, 47, 0.9); border-radius: 50% 50% 0 0 / 100% 100% 0 0;
  transform-origin: 60px 160px; opacity: 0; transition: opacity 0.6s ease;
  filter: drop-shadow(0 0 6px rgba(224, 68, 47, 0.6));
}
.damage i.on { opacity: 1; transition: none; }

.vignette-hurt {
  position: absolute; inset: 0; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 45%, rgba(120, 0, 0, 0.55) 100%);
}

.compass {
  position: absolute; left: 50%; top: 18px; width: min(420px, 70vw); height: 26px; transform: translateX(-50%);
  overflow: hidden;
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent);
  mask-image: linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent);
}
.compass-strip { position: absolute; top: 0; left: 0; height: 100%; white-space: nowrap; font-size: 12px; letter-spacing: 0.1em; color: rgba(232, 228, 216, 0.75); }
.compass-strip span { position: absolute; top: 4px; transform: translateX(-50%); }
.compass-strip span.tick { top: 16px; width: 1px; height: 7px; background: rgba(232, 228, 216, 0.4); }
.compass-strip span.major { color: var(--ink); font-weight: 600; }
.compass-mark { position: absolute; top: 0; width: 0; height: 100%; }
.compass-mark::before {
  content: ''; position: absolute; left: -6px; top: 2px; width: 12px; height: 12px;
  background: var(--brass); transform: rotate(45deg); box-shadow: 0 0 8px rgba(214, 165, 74, 0.8);
}
.compass-mark span { position: absolute; left: 10px; top: 0; font-size: 11px; color: var(--brass); white-space: nowrap; }

.objective {
  position: absolute; left: 24px; top: 20px; max-width: 340px;
  padding: 10px 14px; background: linear-gradient(90deg, rgba(10, 10, 9, 0.6), transparent);
  border-left: 2px solid var(--brass);
}
.objective-label { margin: 0; font-size: 10px; letter-spacing: 0.24em; text-transform: uppercase; color: var(--brass); }
.objective-text { margin: 3px 0 0; font-family: var(--type); font-size: 15px; color: var(--ink); text-shadow: 0 1px 3px #000; }
.objective.flash { animation: objflash 1.6s ease; }
@keyframes objflash { 0%, 30% { background: linear-gradient(90deg, rgba(214, 165, 74, 0.35), transparent); } 100% { background: linear-gradient(90deg, rgba(10, 10, 9, 0.6), transparent); } }

.notice {
  position: absolute; left: 50%; top: 22%; transform: translateX(-50%);
  font-family: var(--type); font-size: 20px; text-align: center; color: var(--ink);
  text-shadow: 0 2px 8px #000, 0 0 2px #000; opacity: 0; transition: opacity 0.5s ease; white-space: nowrap;
}
.notice.on { opacity: 1; }
.notice small { display: block; font-size: 13px; color: var(--muted); margin-top: 4px; }

.prompt {
  position: absolute; left: 50%; top: 62%; transform: translateX(-50%);
  padding: 6px 12px; font-size: 14px; letter-spacing: 0.04em; background: rgba(10, 10, 9, 0.6); border: 1px solid var(--line-strong);
}
.prompt b { color: var(--brass); }

.grenade-warn { position: absolute; left: 50%; top: 38%; transform: translateX(-50%); }
.grenade-warn span {
  display: inline-block; padding: 4px 10px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase;
  color: #fff; background: rgba(224, 68, 47, 0.85); animation: blink 0.4s steps(2) infinite;
}
@keyframes blink { 50% { opacity: 0.4; } }

.detect { position: absolute; left: 50%; top: 50%; width: 0; height: 0; }
.detect i {
  position: absolute; left: -9px; top: -120px; width: 18px; height: 22px;
  transform-origin: 9px 120px;
  background: linear-gradient(to top, rgba(214, 165, 74, 0.1), rgba(214, 165, 74, 0.9));
  clip-path: polygon(50% 0, 100% 100%, 0 100%);
}
.detect i.alert { background: linear-gradient(to top, rgba(224, 68, 47, 0.2), rgba(224, 68, 47, 0.95)); }

.status { position: absolute; left: 24px; bottom: 24px; width: 220px; }
.health { height: 6px; background: rgba(255, 255, 255, 0.12); border: 1px solid rgba(0, 0, 0, 0.5); }
.health-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #b9b29e, #e8e4d8); transition: width 0.2s ease; }
.health-fill.low { background: var(--red); }
.stance { margin: 6px 0 0; font-size: 11px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--muted); text-shadow: 0 1px 2px #000; }

.weapon { position: absolute; right: 26px; bottom: 22px; text-align: right; text-shadow: 0 1px 3px #000; }
.weapon-name { margin: 0; font-size: 12px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--muted); }
.ammo { margin: 0; font-size: 34px; font-weight: 600; line-height: 1.1; }
.ammo span { font-size: 18px; color: var(--muted); margin-left: 6px; }
.ammo.low b { color: var(--red); }
.grenades { margin: 2px 0 0; font-size: 12px; color: var(--muted); letter-spacing: 0.08em; }

.debug {
  position: absolute; right: 8px; top: 8px; margin: 0; padding: 6px 8px;
  font: 11px/1.35 ui-monospace, monospace; color: #cfe; background: rgba(0, 0, 0, 0.55);
}

@media (max-width: 640px) {
  .objective { left: 12px; top: 54px; max-width: 70vw; }
  .status { left: 12px; bottom: 12px; width: 150px; }
  .weapon { right: 12px; bottom: 12px; }
  .ammo { font-size: 26px; }
}

