      if (Math.abs(d) < 1e-9) return o >= -h && o <= h;
      let t1 = (-h - o) / d, t2 = (h - o) / d, sg = -1;
      if (t1 > t2) { const tt = t1; t1 = t2; t2 = tt; sg = 1; }
