    }
    const rx = x - col.x, rz = z - col.z;
    const lx = rx * col.c - rz * col.s, lz = rx * col.s + rz * col.c;
    const qx = Math.max(Math.abs(lx) - col.hx, 0), qz = Math.max(Math.abs(lz) - col.hz, 0);
