  function pushOut(pos, r, feet, height, step, mask = MOVE) {
    let hitAny = false;
    for (let iter = 0; iter < 3; iter++) {
      let moved = false;
      query(pos.x - r - 0.1, pos.z - r - 0.1, pos.x + r + 0.1, pos.z + r + 0.1, near);
      for (const col of near) {
        if (!(col.flags & mask)) continue;
