    geo.computeBoundingBox();
    const mesh = new THREE.Mesh(geo, material);
    mesh.name = 'terrain_chunk';
    mesh.matrixAutoUpdate = false;
    return mesh;
  }

  return { height, normal, raycast, surfaceAt, group, material, grid: { H, nx, nz, minX, minZ, res: RES } };
