        float wetLow = (b.x + b.w * 0.6) * (1.0 - rockW);
        float pMask = smoothstep(0.42, 0.7, texture2D(tForest, vWPos.xz / 31.0).a * 0.7 + (1.0 - hts.x) * 0.5);
        tPuddle = wetLow * smoothstep(0.35, 0.55, pMask - nb.w * 0.1 + (1.0 - hts.x) * 0.25) * uWet;
