            #ifdef USE_INSTANCING
              on = mat3(instanceMatrix) * on;
            #endif
            vWNormalM = normalize(mat3(modelMatrix) * on);
            vec4 wp = vec4(transformed, 1.0);
            #ifdef USE_INSTANCING
