    const t = ctx.currentTime;
    const clicks = kind === 'garand' ? [0.15, 0.9, 1.35, 1.7] : [0.2, 0.9, 1.5, 1.95];
    clicks.forEach((dt, i) => burst(sfx, t + dt, { dur: 0.05, peak: 0.25 + (i === clicks.length - 1 ? 0.15 : 0), type: 'bandpass', freq: 2200 + i * 500, q: 3 }));
