      return bones[name] ? bones[name].getWorldPosition(out) : out.copy(root.position);
    },

    dispose() {
      shadow.parent?.remove(shadow);
      root.parent?.remove(root);
      mixer.stopAllAction();
    },
  };
  return state;
}

