          e.vel.multiplyScalar(0.45);
          if (Math.abs(vn) > 1.5) G.audio.grenadeBounce(e.pos.x, e.pos.y, e.pos.z);
          if (e.vel.length() < 0.6 && hit.ny > 0.6) { e.rest = true; e.vel.set(0, 0, 0); }
