along(LANE, 4, 6.2, (x, z, yaw) => { if (Math.abs(z - 34) > 4 && z < 80) P('hedge', x, z, yaw + (Math.round(z) % 8 < 4 ? 0 : 180), { veg: true }); }, -26);
