for (let i = 0; i < 40; i++) { if (document.querySelector('[data-screen="briefing"].on')) break; await new Promise(r=>setTimeout(r,500)); } document.querySelector('[data-action="start"]').click(); await new Promise(r=>setTimeout(r,600));
const H = window.hedgerow, G = H.G, p = G.player;
p.pos.set(0.5, G.world.groundAt(0.5, 70, 100, 0.5), 70); G.rig.yaw = 0; G.rig.pitch = 0;
await new Promise(r=>setTimeout(r,3000));
const target = G.enemies.find(e => e.group === 'gate' && e.type === 'rifle' && !e.dead);
const log = [];
for (let k = 0; k < 6; k++) {
  const c = G.camera.position; const t = target.char.boneWorld('chest');
  const dx = t.x - c.x, dy = t.y - c.y, dz = t.z - c.z;
  G.rig.yaw = Math.atan2(dx, dz); G.rig.pitch = Math.atan2(dy, Math.hypot(dx, dz));
  H.input.test.aim(true);
  await new Promise(r=>setTimeout(r,500));
  H.input.test.click();
  await new Promise(r=>setTimeout(r,250));
  log.push({hp: target.health.toFixed(0), dead: target.dead, shots: G.stats.shots, hits: G.stats.hits, mag: p.ammo.garand.mag});
  if (target.dead) break;
}
H.input.test.aim(false);
JSON.stringify(log)

