for (let i = 0; i < 60; i++) { if (document.querySelector('[data-screen="briefing"].on')) break; await new Promise(r=>setTimeout(r,500)); } document.querySelector('[data-action="start"]').click(); await new Promise(r=>setTimeout(r,600));
window.walk = async (pts, opts = {}) => {
  const H = window.hedgerow, G = H.G, p = G.player;
  const kd = c => window.dispatchEvent(new KeyboardEvent('keydown', {code: c})); const ku = c => window.dispatchEvent(new KeyboardEvent('keyup', {code: c}));
  const log = [];
  if (opts.from) { p.pos.set(opts.from[0], G.world.groundAt(opts.from[0], opts.from[1], 1e3, 0.5), opts.from[1]); }
  kd('KeyW'); if (!opts.walk) kd('Shift');
  for (const [x, z] of pts) {
    let best = 1e9, stuckT = 0, t0 = performance.now();
    while (true) {
      const d = Math.hypot(x - p.pos.x, z - p.pos.z);
      if (d < 1.2) break;
      G.rig.yaw = Math.atan2(x - p.pos.x, z - p.pos.z); G.rig.pitch = 0;
      if (d < best - 0.05) { best = d; stuckT = performance.now(); }
      if (performance.now() - stuckT > 2500) { log.push({stuck: [+p.pos.x.toFixed(1), +p.pos.y.toFixed(1), +p.pos.z.toFixed(1)], to: [x, z]}); p.pos.set(x, G.world.groundAt(x, z, 1e3, 0.5), z); break; }
      if (performance.now() - t0 > 40000) { log.push({timeout: [x, z]}); break; }
      await new Promise(r => setTimeout(r, 60));
    }
  }
  ku('KeyW'); ku('Shift');
  log.push({end: p.pos.toArray().map(v => +v.toFixed(1)), obj: G.mission.index});
  return log;
};
JSON.stringify(await window.walk([[0.5,30],[0,80],[-3.5,86.5],[-3,93],[2.5,112],[2.5,122],[-0.8,129],[0,145],[0,160]]))

