const kd = c => window.dispatchEvent(new KeyboardEvent('keydown', {code: c})); const ku = c => window.dispatchEvent(new KeyboardEvent('keyup', {code: c}));
const walk = async (pts, from) => {
  const log = [];
  if (from) p.pos.set(from[0], G.world.groundAt(from[0], from[1], 1e3, 0.5), from[1]);
  kd('KeyW'); kd('Shift');
  for (const [x, z] of pts) {
    let best = 1e9, stuckT = G.time, t0 = G.time;
    while (true) {
      const d = Math.hypot(x - p.pos.x, z - p.pos.z);
      if (d < 1.2) break;
      G.rig.yaw = Math.atan2(x - p.pos.x, z - p.pos.z); G.rig.pitch = 0;
      if (d < best - 0.05) { best = d; stuckT = G.time; }
      if (G.time - stuckT > 2.5) { log.push({stuck: [+p.pos.x.toFixed(1), +p.pos.y.toFixed(1), +p.pos.z.toFixed(1)], to: [x, z]}); p.pos.set(x, G.world.groundAt(x, z, 1e3, 0.5), z); break; }
      if (G.time - t0 > 40) { log.push({timeout: [x, z]}); break; }
      await new Promise(r => setTimeout(r, 50));
    }
  }
  ku('KeyW'); ku('Shift');
  log.push({end: p.pos.toArray().map(v => +v.toFixed(1)), obj: G.mission.index, t: G.time.toFixed(1)});
  return log;
};
