    }""", """    let move;
    const crouch = e.stance === 'crouch';
    if (crouch) move = speed > 0.3 ? 'crouch_walk' : 'crouch_idle';
    else if (speed < 0.3) move = 'idle';
    else if (speed > 3) move = 'run';
    else {
