  }

  function step(dt) {
    if (asleep) return;
    const sub = 2, h = Math.min(dt, 1 / 30) / sub;
    let moved = 0;
    for (let s = 0; s < sub; s++) {
      for (let i = 0; i < n; i++) {
        const p = pos[i], q = prev[i];
        tmp.copy(p);
