    update(t) {
      while (next < list.length && t >= list[next].t) fire(list[next++].name);
    },
    /* finished or interrupted: put everything back */
    end() {
      char.holdLeft(null);
      if (seated) seated.visible = true;
      next = list.length;
    },
  };
}

