import L from '/Users/vojta/Dev/protocodus.github.io/.claude/worktrees/hedgerow/fun/hedgerow/js/levels/saint-clair.js';
const DEG = Math.PI / 180;
const debris = { house_b: [-3.76, -3.0, -0.77, 1.88], house_e: [4.61, 5.5, 1.48, 3.85], house_g: [-4.94, -4.12, -1.77, -0.08] };
const toWorld = (p, x, z) => { const c = Math.cos(p.yaw * DEG), s = Math.sin(p.yaw * DEG); return [p.x + x * c + z * s, p.z - x * s + z * c]; };
const toLocal = (p, wx, wz) => { const c = Math.cos(p.yaw * DEG), s = Math.sin(p.yaw * DEG); const dx = wx - p.x, dz = wz - p.z; return [dx * c - dz * s, dx * s + dz * c]; };
for (const p of L.props) {
  const d = debris[p.m]; if (!d) continue;
  const [x0, x1, z0, z1] = d;
  const corners = [[x0, z0], [x1, z1]].map(([x, z]) => toWorld(p, x, z).map((v) => v.toFixed(1)));
  const near = [];
  for (const q of L.props) {
    if (q === p) continue;
    const [lx, lz] = toLocal(p, q.x, q.z);
    const m = 1.2;
    if (lx > x0 - m && lx < x1 + m && lz > z0 - m && lz < z1 + m) near.push(`${q.m}@${q.x.toFixed(1)},${q.z.toFixed(1)}`);
  }
  console.log(p.m, `at ${p.x},${p.z} yaw ${p.yaw}`, 'debris', corners.join(' .. '), near.length ? 'NEAR: ' + near.join(' ') : 'clear');
}
EOF
