import { readFileSync } from 'node:fs';
import L from '/Users/vojta/Dev/protocodus.github.io/.claude/worktrees/hedgerow/fun/hedgerow/js/levels/saint-clair.js';
const cols = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const DEG = Math.PI / 180;
const toLocal = (p, wx, wz) => { const c = Math.cos(p.yaw * DEG), s = Math.sin(p.yaw * DEG); const dx = wx - p.x, dz = wz - p.z; return [dx * c - dz * s, dx * s + dz * c]; };
for (const lamp of L.props.filter((p) => p.m === 'wall_lamp')) {
  // the lamp's back plate is at local z 0, facing local +z; the wall should be just behind it
  const c = Math.cos(lamp.yaw * DEG), s = Math.sin(lamp.yaw * DEG);
  const bx = lamp.x - 0.15 * s, bz = lamp.z - 0.15 * c;
  const hits = [];
  for (const p of L.props) {
    const cl = cols[p.m]; if (!cl || p === lamp) continue;
    const [lx, lz] = toLocal(p, bx, bz);
    for (const k of cl) if (k.type === 'box') {
      const a = -(k.ry || 0); const dx = lx - k.c[0], dz = lz - k.c[2];
      const ux = dx * Math.cos(a) - dz * Math.sin(a), uz = dx * Math.sin(a) + dz * Math.cos(a);
      if (Math.abs(ux) <= k.h[0] && Math.abs(uz) <= k.h[2] && k.c[1] + k.h[1] > 2.5) hits.push(p.m);
    }
  }
  console.log(`wall_lamp ${lamp.x},${lamp.z} yaw ${lamp.yaw}:`, hits.length ? 'on ' + [...new Set(hits)].join(',') : 'NO WALL BEHIND');
}
EOF
