REDACTED && cat > $S/mount-check.mjs <<'EOF'
import { readFileSync } from 'node:fs';
import L from '/Users/vojta/Dev/protocodus.github.io/.claude/worktrees/hedgerow/fun/hedgerow/js/levels/saint-clair.js';
const cols = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const DEG = Math.PI / 180;
const toLocal = (p, wx, wz) => { const c = Math.cos(p.yaw * DEG), s = Math.sin(p.yaw * DEG); const dx = wx - p.x, dz = wz - p.z; return [dx * c - dz * s, dx * s + dz * c]; };
const HALF = { wall_lamp: 0.11, ivy_patch: 0.7, bicycle: 0.9 };
const wallAt = (x, z, minTop) => {
  for (const p of L.props) {
    const cl = cols[p.m]; if (!cl || HALF[p.m]) continue;
    const [lx, lz] = toLocal(p, x, z);
    for (const k of cl) if (k.type === 'box' && k.c[1] + k.h[1] >= minTop) {
      const a = -(k.ry || 0); const dx = lx - k.c[0], dz = lz - k.c[2];
      const ux = dx * Math.cos(a) - dz * Math.sin(a), uz = dx * Math.sin(a) + dz * Math.cos(a);
      if (Math.abs(ux) <= k.h[0] && Math.abs(uz) <= k.h[2]) return p.m;
    }
  }
  return null;
};
for (const m of L.props.filter((p) => HALF[p.m])) {
  const c = Math.cos(m.yaw * DEG), s = Math.sin(m.yaw * DEG);
  // back is local -z; sideways is local x
  const res = [-1, 1].map((side) => {
    const x = m.x + side * HALF[m.m] * c - 0.2 * s, z = m.z - side * HALF[m.m] * s - 0.2 * c;
    return wallAt(x, z, m.m === 'bicycle' ? 1.0 : 2.4);
  });
  console.log(`${m.m.padEnd(10)} ${m.x},${m.z}`, res.every(Boolean) ? 'on ' + res[0] : `OFF THE WALL (${res.map((r) => r || '-').join(' / ')})`);
}
EOF
node --import ./tests/three-hooks.mjs $S/mount-check.mjs $S/house-cols.json 2>&1 | tail -20; ls tools/blender/previews/village/ | grep -E "^(house_[abde]|barn)" | head -30

