1	/* Hedgerow — the land beyond the level.
2	
3	   A coarse ring of terrain round the playable area (out to ~1 km): rolling
4	   Norman bocage — a patchwork of fields and woods, hedgerow lines along the
5	   field edges — covered with the trees' far LODs (crossed impostor cards, a
6	   few triangles each) and the level's own distant scenery (a neighbouring
7	   village on a hill). It sits a little below the real terrain where they
8	   overlap, so the seam never shows. Static: built once, never updated. */
9	
10	import * as THREE from 'three';
11	import { fbm2, lerp, rng, smoothstep, clamp } from './util.js';
12	import { createStaticBatcher } from './assets.js';
13	
14	export function buildDistance(G, L, { models, matlib, material }) {
15	  const group = new THREE.Group();
16	  group.name = 'distance';
17	  const B = L.bounds;
18	  const F = L.far || {};
19	  const cx0 = B.minX, cx1 = B.maxX, cz0 = B.minZ, cz1 = B.maxZ;
20	  const outside = (x, z) => Math.hypot(Math.max(0, cx0 - x, x - cx1), Math.max(0, cz0 - z, z - cz1));
21	
22	  /* the far ground */
23	  const hills = F.height || ((x, z) => 18 + 22 * fbm2(x / 420 + 1.3, z / 420 - 2.1, 4) + 8 * fbm2(x / 150, z / 150, 3));
24	  const woods = F.woods || ((x, z) => smoothstep(0.08, 0.22, fbm2(x / 230 + 7.7, z / 230 - 4.4, 3)));
25	  const height = (x, z) => {
26	    const d = outside(x, z);
