cat > $S/veg-cost.mjs <<'EOF'
import { readFileSync } from 'node:fs';
import L from '/Users/vojta/Dev/protocodus.github.io/.claude/worktrees/hedgerow/fun/hedgerow/js/levels/saint-clair.js';
const tris = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const counts = {};
for (const s of L.scatter) counts[s.m] = (counts[s.m] || 0) + 1;
console.log('scatter', L.scatter.length, Object.entries(counts).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k}:${v}`).join(' '));
for (const [cx, cz] of [[0, 120], [0, 300], [0, 400], [-20, 470], [0, 540]]) {
  const row = [];
  for (const [nearBig, near] of [[52, 52], [78, 52], [65, 52]]) {
