const mat = new THREE.MeshBasicMaterial();
const models = new Map(names.map((n) => [n, { name: n, prims: [{ geometry: new THREE.BufferGeometry(), material: mat }] }]));
const matlib = { resolve: (m) => m, get: () => mat };
const t0 = performance.now();
const far = buildDistance({}, L, { models, matlib, material: mat });
console.log('built in', (performance.now() - t0).toFixed(0), 'ms; far trees', far.farTrees, 'treeline tiles', far.treelines);
const B = L.bounds, m4 = new THREE.Matrix4(), p = new THREE.Vector3(), q = new THREE.Quaternion(), sc = new THREE.Vector3();
let worstFacing = 1, aboveGround = 0, mirrored = 0, n = 0;
const counts = {};
for (const mesh of far.group.children) {
  if (!mesh.isInstancedMesh) continue;
  counts[mesh.name] = mesh.count;
  if (!/treeline/.test(mesh.name)) continue;
  for (let i = 0; i < mesh.count; i++) {
    mesh.getMatrixAt(i, m4); m4.decompose(p, q, sc);
    const fwd = new THREE.Vector3(0, 0, 1).applyQuaternion(q);
    const tx = Math.min(B.maxX, Math.max(B.minX, p.x)) - p.x, tz = Math.min(B.maxZ, Math.max(B.minZ, p.z)) - p.z;
    const to = new THREE.Vector3(tx, 0, tz).normalize();
    worstFacing = Math.min(worstFacing, fwd.dot(to));
    if (m4.determinant() < 0) mirrored++;
    // base below the far ground at the tile's centre
    if (p.y > far.height(p.x, p.z)) aboveGround++;
    n++;
  }
}
