for (const b of L.far.buildings) {
  const ax = Math.min(B.maxX, Math.max(B.minX, b.x)), az = Math.min(B.maxZ, Math.max(B.minZ, b.z));
  let near = Infinity;
  for (const mesh of far.group.children) if (/treeline/.test(mesh.name)) for (let i = 0; i < mesh.count; i++) {
    mesh.getMatrixAt(i, m4); p.setFromMatrixPosition(m4);
    const dx = b.x - ax, dz = b.z - az, t = Math.max(0, Math.min(1, ((p.x - ax) * dx + (p.z - az) * dz) / (dx * dx + dz * dz)));
    near = Math.min(near, Math.hypot(p.x - ax - dx * t, p.z - az - dz * t));
  }
  if (near < 75) console.log('BLOCKED', b.m, b.x, b.z, near.toFixed(0));
}
console.log('sightlines checked');
EOF
