// Run with: node fun/hedgerow/tests/character-check.mjs
// The aim pitch on the spine must not accumulate. three's AnimationMixer
// only writes a bone when the animated value changed since the previous
// frame, so a held pose (aim) leaves last frame's bone rotation in place: a
// pitch applied on top of it every frame would turn the upper body round and
// round. The spine must hold the clip's pose plus exactly one aim pitch.
import './three-hooks.mjs';
import assert from 'node:assert/strict';
const THREE = await import('three');
const { createCharacter } = await import('../js/character.js');

// a small rig: root > hips > spine > chest > neck > head, hand_r with the socket
function bone(name, parent, y) {
  const b = new THREE.Bone();
  b.name = name;
  b.position.y = y;
  if (parent) parent.add(b);
  return b;
}
const scene = new THREE.Group();
scene.name = 'rig';
const root = bone('root', null, 0);
scene.add(root);
const hips = bone('hips', root, 1.0);
const spine = bone('spine', hips, 0.15);
// Module hooks for the checks that import game code using three.js: the bare
// specifier 'three' resolves to the site's vendored copy (as the import map
// does in the browser). Import this file first.
import { registerHooks } from 'node:module';

const THREE_URL = new URL('../../../assets/vendor/three/three.module.min.js', import.meta.url).href;

registerHooks({
  resolve(specifier, context, next) {
    if (specifier === 'three') return { url: THREE_URL, shortCircuit: true, format: 'module' };
    return next(specifier, context);
  },
});

// the bits of the DOM the game touches while building characters
globalThis.document ??= {
  createElement: () => ({
    width: 0, height: 0,
    getContext: () => ({
      createRadialGradient: () => ({ addColorStop() {} }),
      createLinearGradient: () => ({ addColorStop() {} }),
      fillRect() {}, beginPath() {}, arc() {}, fill() {}, moveTo() {}, lineTo() {}, stroke() {},
      putImageData() {}, createImageData: (w, h) => ({ data: new Uint8ClampedArray(w * h * 4) }),
    }),
  }),
};
