const G = window.hedgerow.G, inp = window.hedgerow.input;
const THREE = await import('three');
for (let i = 0; i < 40 && G.player.reloading > 0; i++) await new Promise((r) => setTimeout(r, 100));
const cam2 = new THREE.PerspectiveCamera(40, G.camera.aspect, 0.05, 500);
window._cam2 = null;
if (!window._origRender) { window._origRender = G.renderer.render.bind(G.renderer); G.renderer.render = (s, c) => window._origRender(s, window._cam2 || c); }
const place = () => {
  const p = G.player.pos, yaw = G.rig.yaw;
  const f = new THREE.Vector3(Math.sin(yaw), 0, Math.cos(yaw)), left = new THREE.Vector3(Math.cos(yaw), 0, -Math.sin(yaw));
  cam2.position.set(p.x, p.y + 1.45, p.z).addScaledVector(f, 1.6).addScaledVector(left, 1.0);
  cam2.lookAt(p.x + f.x * 0.2, p.y + 1.2, p.z + f.z * 0.2);
};
const orig = inp.fired; inp.fired = () => true;
for (let i = 0; i < 80 && !(G.player.reloading > 0); i++) await new Promise((r) => setTimeout(r, 50));
inp.fired = orig;
const total = G.player.reloadTotal;
window._cam2 = cam2;
for (let i = 0; i < 200 && 1 - G.player.reloading / total < 0.45; i++) { place(); await new Promise((r) => setTimeout(r, 10)); }
place();
// hold the pose: freeze the game's time for the shot
window._frozen = true;
const sl = G.player.char?.socketL;
({ progress: (1 - G.player.reloading / total).toFixed(2), leftHandHolds: sl ? sl.children.map((c) => c.name) : 'no socket' })

