for (let i = 0; i < 80 && !(G.player.reloading > 0); i++) await new Promise((r) => setTimeout(r, 50));
inp.fired = orig;
const total = G.player.reloadTotal;
window._pose = window._front;
for (let i = 0; i < 300 && 1 - G.player.reloading / total < 0.42; i++) await new Promise((r) => setTimeout(r, 10));
