1	/* Hedgerow — a soldier on screen.
2	
3	   One rig (soldier.glb) with two outfits. The clips are split by bone into
4	   a lower-body layer (root, hips, legs: walk/run/strafe/crouch) and an
5	   upper-body layer (spine up: idle/aim/reload/throw), each cross-faded on
6	   its own, so a soldier can run while aiming or crouch-walk while
7	   reloading. After the mixer, the spine and chest are bent by the aim
8	   pitch, the weapon rides on the `socket_weapon` empty in the right hand,
9	   and a soft contact shadow sits under the feet. Deaths play the whole
10	   clip on both layers. */
11	
12	import * as THREE from 'three';
13	import { clone as cloneSkinned } from '../assets/utils/SkeletonUtils.js';
14	import { instantiate } from './assets.js';
15	import { mergeGeometries } from '../assets/utils/BufferGeometryUtils.js';
16	import { createRagdoll } from './ragdoll.js';
17	
18	const LOWER = new Set(['root', 'hips', 'thigh_l', 'shin_l', 'foot_l', 'thigh_r', 'shin_r', 'foot_r']);
19	
20	let shadowTex = null;
21	function contactShadowTexture() {
22	  if (shadowTex) return shadowTex;
23	  const c = document.createElement('canvas');
24	  c.width = c.height = 64;
25	  const g = c.getContext('2d');
26	  const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
27	  gr.addColorStop(0, 'rgba(0,0,0,0.75)'); gr.addColorStop(0.5, 'rgba(0,0,0,0.4)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
28	  g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
29	  shadowTex = new THREE.CanvasTexture(c);
30	  return shadowTex;
31	}
32	
33	/* Split every clip into lower/upper halves once per gltf. */
34	function splitClips(gltf) {
35	  if (gltf._split) return gltf._split;
36	  const lower = {}, upper = {}, full = {};
37	  for (const clip of gltf.animations) {
38	    const lo = [], up = [];
39	    for (const t of clip.tracks) {
40	      const bone = t.name.split('.')[0];
41	      (LOWER.has(bone) ? lo : up).push(t);
42	    }
43	    lower[clip.name] = new THREE.AnimationClip(clip.name + '_lo', clip.duration, lo);
44	    upper[clip.name] = new THREE.AnimationClip(clip.name + '_up', clip.duration, up);
45	    full[clip.name] = clip;
46	  }
47	  gltf._split = { lower, upper, full };
48	  return gltf._split;
49	}
50	
51	/* A copy of the rig whose outfits are each one skinned mesh: the palette
52	   colours are baked into the vertex colours and drawn with a single
53	   material, so a soldier costs one draw call instead of one per material.
54	   Used for the enemies; the player keeps the full materials. */
55	export function mergedSoldier(gltf, matlib) {
56	  if (gltf._merged) return gltf._merged;
57	  const scene = cloneSkinned(gltf.scene);
58	  const material = matlib.get('cloth_feldgrau', { variant: 'merged', color: '#ffffff', roughness: 0.82, metalness: 0.02 });
59	  for (const outfit of ['allied', 'axis']) {
60	    const group = scene.getObjectByName(outfit);
61	    if (!group) continue;
62	    const parts = [];
63	    group.traverse((o) => { if (o.isSkinnedMesh) parts.push(o); });
64	    // baked outfits are one material already
65	    if (parts.length < 2 || parts.some(p => p.material?.map)) continue;
66	    const geos = parts.map((m) => {
67	      const g = m.geometry.clone();
68	      const key = (m.material?.name || 'cloth_od').replace(/\.\d+$/, '');
69	      const col = matlib.get(key).color;
70	      const n = g.attributes.position.count;
71	      const src = g.attributes.color;
72	      const c = new Float32Array(n * 3);
73	      for (let i = 0; i < n; i++) {
74	        const k = src ? src.getX(i) : 1, l = src ? src.getY(i) : 1, q = src ? src.getZ(i) : 1;
75	        c[i * 3] = col.r * k; c[i * 3 + 1] = col.g * l; c[i * 3 + 2] = col.b * q;
76	      }
77	      g.setAttribute('color', new THREE.BufferAttribute(c, 3));
78	      if (!g.attributes.uv) g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(n * 2), 2));
79	      for (const name of Object.keys(g.attributes)) {
80	        if (!['position', 'normal', 'uv', 'color', 'skinIndex', 'skinWeight'].includes(name)) g.deleteAttribute(name);
81	      }
82	      // the same attribute types everywhere so they merge
83	      for (const name of ['position', 'normal', 'uv', 'skinWeight']) {
