87	          for (let i = 0; i < a.count; i++) for (let j = 0; j < a.itemSize; j++) f[i * a.itemSize + j] = a.getComponent(i, j);
88	          g.setAttribute(name, new THREE.BufferAttribute(f, a.itemSize));
89	        }
90	      }
91	      const si = g.attributes.skinIndex;
92	      if (si && !(si.array instanceof Uint16Array)) g.setAttribute('skinIndex', new THREE.BufferAttribute(Uint16Array.from(si.array), 4));
93	      return g;
94	    });
95	    const merged = mergeGeometries(geos, false);
96	    if (!merged) continue;
97	    const first = parts[0];
98	    const mesh = new THREE.SkinnedMesh(merged, material);
99	    mesh.name = outfit + '_merged';
100	    mesh.bind(first.skeleton, first.bindMatrix);
101	    mesh.position.copy(first.position); mesh.quaternion.copy(first.quaternion); mesh.scale.copy(first.scale);
102	    const parent = first.parent;
103	    for (const p of parts) p.parent.remove(p);
104	    parent.add(mesh);
105	  }
106	  gltf._merged = { scene, animations: gltf.animations, _split: null, merged: true };
107	  return gltf._merged;
108	}
109	
110	const ONE_SHOT = new Set(['reload', 'throw', 'hit', 'death_fwd', 'death_back', 'death_crumple']);
111	
112	/* A stand-in soldier (capsule body, head, rifle) with the same interface,
113	   used when the rig is not available. */
114	function createStandIn(matlib, { outfit, scene }) {
115	  const root = new THREE.Group();
116	  root.name = 'standin_' + outfit;
117	  const plain = (key) => { const m = matlib.get(key).clone(); m.vertexColors = false; return m; };
118	  const cloth = plain(outfit === 'allied' ? 'cloth_od' : 'cloth_feldgrau');
119	  const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.24, 0.9, 4, 10), cloth);
120	  body.position.y = 0.95;
121	  const head = new THREE.Mesh(new THREE.SphereGeometry(0.13, 12, 8), plain('skin'));
122	  head.position.y = 1.62;
123	  const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.16, 12, 6, 0, Math.PI * 2, 0, Math.PI / 2), plain(outfit === 'allied' ? 'helmet_od' : 'helmet_gray'));
124	  helmet.position.y = 1.65;
125	  const gun = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.08, 1.0), plain('gun_wood'));
126	  gun.position.set(-0.18, 1.35, 0.35);
127	  root.add(body, head, helmet, gun);
128	  const shadow = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 1.1).rotateX(-Math.PI / 2),
129	    new THREE.MeshBasicMaterial({ map: contactShadowTexture(), transparent: true, depthWrite: false, fog: false }));
130	  if (scene) scene.add(shadow);
131	  let dead = false, crouch = 0;
132	  const bonesAt = { head: 1.62, neck: 1.45, hips: 0.95, shin_l: 0.35, shin_r: 0.35, hand_r: 1.3, chest: 1.3, spine: 1.1 };
133	  return {
134	    root, bones: {}, mixer: { time: 0 }, socket: null, meshes: [body, head, helmet, gun], shadow,
135	    get weapon() { return gun; }, get dead() { return dead; }, get upper() { return 'idle'; },
136	    aimPitch: 0, setWeapon() {}, holdLeft() {}, releaseLeft() {}, clipLength: () => null, hasClip: () => false, socketL: null,
137	    animate(move) { crouch = move.startsWith('crouch') ? 1 : 0; },
138	    oneShot() { return 0.5; },
139	    die() { dead = true; },
140	    update(dt, ground) {
141	      const s = dead ? 0.25 : 1 - crouch * 0.35;
142	      root.scale.y += (s - root.scale.y) * Math.min(1, dt * 10);
143	      root.updateMatrixWorld(true);
144	      if (ground != null) shadow.position.set(root.position.x, ground + 0.03, root.position.z);
145	    },
146	    muzzleWorld(out = new THREE.Vector3()) { return gun.localToWorld(out.set(0, 0, 0.5)); },
147	    headWorld(out = new THREE.Vector3()) { return head.getWorldPosition(out); },
148	    boneWorld(name, out = new THREE.Vector3()) {
149	      out.copy(root.position);
150	      out.y += (bonesAt[name] ?? 1) * root.scale.y;
151	      return out;
152	    },
