import { readFileSync } from 'node:fs';
import L from '/Users/vojta/Dev/protocodus.github.io/.claude/worktrees/hedgerow/fun/hedgerow/js/levels/saint-clair.js';
const M = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const DEG = Math.PI / 180;
const W = (p, x, z) => { const c = Math.cos(p.yaw * DEG), s = Math.sin(p.yaw * DEG), k = p.scale || 1; return [p.x + (x * c + z * s) * k, p.z + (-x * s + z * c) * k]; };
const Lc = (p, wx, wz) => { const c = Math.cos(p.yaw * DEG), s = Math.sin(p.yaw * DEG), k = p.scale || 1, dx = wx - p.x, dz = wz - p.z; return [(dx * c - dz * s) / k, (dx * s + dz * c) / k]; };
const inCol = (p, wx, wz) => {
  const [lx, lz] = Lc(p, wx, wz);
  for (const k of M[p.m].cols) {
    if (k.type === 'box') { const a = -(k.ry || 0), dx = lx - k.c[0], dz = lz - k.c[2];
      if (Math.abs(dx * Math.cos(a) - dz * Math.sin(a)) < k.h[0] - 0.02 && Math.abs(dx * Math.sin(a) + dz * Math.cos(a)) < k.h[2] - 0.02) return true; }
    else if (Math.hypot(lx - k.c[0], lz - k.c[2]) < k.r - 0.02) return true;
  }
  return false;
};
const GROWN = ['sandbags', 'sandbags_low', 'sandbags_curve', 'sandbags_ruined', 'crate', 'crate_large'];
let n = 0, hits = [];
for (const p of L.props.filter((q) => GROWN.includes(q.m))) {
  n++;
  const { min, max } = M[p.m];
  // the footprint's edge, sampled every 10 cm
  const pts = [];
  for (let t = 0; t <= 1.0001; t += 0.05) pts.push([min[0] + (max[0] - min[0]) * t, min[2]], [min[0] + (max[0] - min[0]) * t, max[2]], [min[0], min[2] + (max[2] - min[2]) * t], [max[0], min[2] + (max[2] - min[2]) * t]);
  const into = new Set();
  for (const q of L.props) {
    if (q === p || !M[q.m] || !M[q.m].cols.length || q.veg) continue;
    if (Math.hypot(q.x - p.x, q.z - p.z) > 25) continue;
    for (const [lx, lz] of pts) { const [wx, wz] = W(p, lx, lz); if (inCol(q, wx, wz)) { into.add(q.m); break; } }
  }
  if (into.size) hits.push(`${p.m} at (${p.x}, ${p.z}) yaw ${p.yaw}: edge inside ${[...into].join(', ')}`);
}
console.log(`${n} grown props checked`);
for (const h of hits) console.log('  ' + h);
