1	/* Hedgerow — a soldier on screen.
2	
3	   One rig (soldier.glb) with two outfits. The clips are split by bone into
4	   a lower-body layer (root, hips, legs: walk/run/strafe/crouch) and an
5	   upper-body layer (spine up: idle/aim/reload/throw), each cross-faded on
6	   its own, so a soldier can run while aiming or crouch-walk while
7	   reloading. After the mixer, the spine and chest are bent by the aim
8	   pitch, the weapon rides on the `socket_weapon` empty in the right hand,
9	   and a soft contact shadow sits under the feet. Deaths play the whole
10	   clip on both layers. */
11	
12	import * as THREE from 'three';
13	import { clone as cloneSkinned } from '../assets/utils/SkeletonUtils.js';
14	import { instantiate } from './assets.js';
15	import { mergeGeometries } from '../assets/utils/BufferGeometryUtils.js';
16	import { createRagdoll } from './ragdoll.js';
17	
18	const LOWER = new Set(['root', 'hips', 'thigh_l', 'shin_l', 'foot_l', 'thigh_r', 'shin_r', 'foot_r']);
19	
20	let shadowTex = null;
21	function contactShadowTexture() {
22	  if (shadowTex) return shadowTex;
23	  const c = document.createElement('canvas');
24	  c.width = c.height = 64;
25	  const g = c.getContext('2d');
26	  const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
27	  gr.addColorStop(0, 'rgba(0,0,0,0.75)'); gr.addColorStop(0.5, 'rgba(0,0,0,0.4)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
28	  g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
29	  shadowTex = new THREE.CanvasTexture(c);
30	  return shadowTex;
31	}
32	
33	/* Split every clip into lower/upper halves once per gltf. */
34	function splitClips(gltf) {
35	  if (gltf._split) return gltf._split;
36	  const lower = {}, upper = {}, full = {};
37	  for (const clip of gltf.animations) {
38	    const lo = [], up = [];
39	    for (const t of clip.tracks) {
40	      const bone = t.name.split('.')[0];
41	      (LOWER.has(bone) ? lo : up).push(t);
42	    }
43	    lower[clip.name] = new THREE.AnimationClip(clip.name + '_lo', clip.duration, lo);
44	    upper[clip.name] = new THREE.AnimationClip(clip.name + '_up', clip.duration, up);
45	    full[clip.name] = clip;
46	  }
47	  gltf._split = { lower, upper, full };
48	  return gltf._split;
49	}
50	
51	/* A copy of the rig whose outfits are each one skinned mesh: the palette
52	   colours are baked into the vertex colours and drawn with a single
53	   material, so a soldier costs one draw call instead of one per material.
54	   Used for the enemies; the player keeps the full materials. */
55	export function mergedSoldier(gltf, matlib) {
56	  if (gltf._merged) return gltf._merged;
57	  const scene = cloneSkinned(gltf.scene);
58	  const material = matlib.get('cloth_feldgrau', { variant: 'merged', color: '#ffffff', roughness: 0.82, metalness: 0.02 });
59	  for (const outfit of ['allied', 'axis']) {
60	    const group = scene.getObjectByName(outfit);
61	    if (!group) continue;
62	    const parts = [];
63	    group.traverse((o) => { if (o.isSkinnedMesh) parts.push(o); });
64	    // baked outfits are one material already
65	    if (parts.length < 2 || parts.some(p => p.material?.map)) continue;
66	    const geos = parts.map((m) => {
67	      const g = m.geometry.clone();
68	      const key = (m.material?.name || 'cloth_od').replace(/\.\d+$/, '');
69	      const col = matlib.get(key).color;
70	      const n = g.attributes.position.count;
71	      const src = g.attributes.color;
72	      const c = new Float32Array(n * 3);
73	      for (let i = 0; i < n; i++) {
74	        const k = src ? src.getX(i) : 1, l = src ? src.getY(i) : 1, q = src ? src.getZ(i) : 1;
75	        c[i * 3] = col.r * k; c[i * 3 + 1] = col.g * l; c[i * 3 + 2] = col.b * q;
76	      }
77	      g.setAttribute('color', new THREE.BufferAttribute(c, 3));
78	      if (!g.attributes.uv) g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(n * 2), 2));
79	      for (const name of Object.keys(g.attributes)) {
80	        if (!['position', 'normal', 'uv', 'color', 'skinIndex', 'skinWeight'].includes(name)) g.deleteAttribute(name);
81	      }
82	      // the same attribute types everywhere so they merge
83	      for (const name of ['position', 'normal', 'uv', 'skinWeight']) {
84	        const a = g.attributes[name];
85	        if (a && !(a.array instanceof Float32Array)) {
86	          const f = new Float32Array(a.count * a.itemSize);
87	          for (let i = 0; i < a.count; i++) for (let j = 0; j < a.itemSize; j++) f[i * a.itemSize + j] = a.getComponent(i, j);
88	          g.setAttribute(name, new THREE.BufferAttribute(f, a.itemSize));
89	        }
90	      }
91	      const si = g.attributes.skinIndex;
92	      if (si && !(si.array instanceof Uint16Array)) g.setAttribute('skinIndex', new THREE.BufferAttribute(Uint16Array.from(si.array), 4));
93	      return g;
94	    });
95	    const merged = mergeGeometries(geos, false);
96	    if (!merged) continue;
97	    const first = parts[0];
98	    const mesh = new THREE.SkinnedMesh(merged, material);
99	    mesh.name = outfit + '_merged';
100	    mesh.bind(first.skeleton, first.bindMatrix);
101	    mesh.position.copy(first.position); mesh.quaternion.copy(first.quaternion); mesh.scale.copy(first.scale);
102	    const parent = first.parent;
103	    for (const p of parts) p.parent.remove(p);
104	    parent.add(mesh);
105	  }
106	  gltf._merged = { scene, animations: gltf.animations, _split: null, merged: true };
107	  return gltf._merged;
108	}
109	
110	const ONE_SHOT = new Set(['reload', 'throw', 'hit', 'death_fwd', 'death_back', 'death_crumple']);
111	
112	/* A stand-in soldier (capsule body, head, rifle) with the same interface,
113	   used when the rig is not available. */
114	function createStandIn(matlib, { outfit, scene }) {
115	  const root = new THREE.Group();
116	  root.name = 'standin_' + outfit;
117	  const plain = (key) => { const m = matlib.get(key).clone(); m.vertexColors = false; return m; };
118	  const cloth = plain(outfit === 'allied' ? 'cloth_od' : 'cloth_feldgrau');
119	  const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.24, 0.9, 4, 10), cloth);
120	  body.position.y = 0.95;
121	  const head = new THREE.Mesh(new THREE.SphereGeometry(0.13, 12, 8), plain('skin'));
122	  head.position.y = 1.62;
123	  const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.16, 12, 6, 0, Math.PI * 2, 0, Math.PI / 2), plain(outfit === 'allied' ? 'helmet_od' : 'helmet_gray'));
124	  helmet.position.y = 1.65;
125	  const gun = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.08, 1.0), plain('gun_wood'));
126	  gun.position.set(-0.18, 1.35, 0.35);
127	  root.add(body, head, helmet, gun);
128	  const shadow = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 1.1).rotateX(-Math.PI / 2),
129	    new THREE.MeshBasicMaterial({ map: contactShadowTexture(), transparent: true, depthWrite: false, fog: false }));
130	  if (scene) scene.add(shadow);
131	  let dead = false, crouch = 0;
132	  const bonesAt = { head: 1.62, neck: 1.45, hips: 0.95, shin_l: 0.35, shin_r: 0.35, hand_r: 1.3, chest: 1.3, spine: 1.1 };
133	  return {
134	    root, bones: {}, mixer: { time: 0 }, socket: null, meshes: [body, head, helmet, gun], shadow,
135	    get weapon() { return gun; }, get dead() { return dead; }, get upper() { return 'idle'; },
136	    aimPitch: 0, setWeapon() {}, holdLeft() {}, releaseLeft() {}, clipLength: () => null, hasClip: () => false, socketL: null,
137	    animate(move) { crouch = move.startsWith('crouch') ? 1 : 0; },
138	    oneShot() { return 0.5; },
139	    die() { dead = true; },
140	    update(dt, ground) {
141	      const s = dead ? 0.25 : 1 - crouch * 0.35;
142	      root.scale.y += (s - root.scale.y) * Math.min(1, dt * 10);
143	      root.updateMatrixWorld(true);
144	      if (ground != null) shadow.position.set(root.position.x, ground + 0.03, root.position.z);
145	    },
146	    muzzleWorld(out = new THREE.Vector3()) { return gun.localToWorld(out.set(0, 0, 0.5)); },
147	    headWorld(out = new THREE.Vector3()) { return head.getWorldPosition(out); },
148	    boneWorld(name, out = new THREE.Vector3()) {
149	      out.copy(root.position);
150	      out.y += (bonesAt[name] ?? 1) * root.scale.y;
151	      return out;
152	    },
153	    dispose() { shadow.parent?.remove(shadow); root.parent?.remove(root); },
154	  };
155	}
156	
157	export function createCharacter(gltf, matlib, { outfit = 'allied', weaponModel = null, grenadeModel = null, scene }) {
158	  if (!gltf) return createStandIn(matlib, { outfit, scene });
159	  const root = cloneSkinned(gltf.scene);
160	  root.name = 'soldier_' + outfit;
161	  const other = outfit === 'allied' ? 'axis' : 'allied';
162	  const meshes = [];
163	  root.traverse((o) => {
164	    if (o.isSkinnedMesh || o.isMesh) {
165	      let owner = o;
166	      while (owner && owner.name !== outfit && owner.name !== other) owner = owner.parent;
167	      const name = owner ? owner.name : '';
168	      if (name === other || (o.name.startsWith(other))) { o.visible = false; return; }
169	      if (!o.name.endsWith('_merged')) o.material = matlib.resolve(o.material);
170	      o.frustumCulled = false;
171	      meshes.push(o);
172	    }
173	  });
174	  // drop the other outfit entirely (saves skinning work)
175	  const drop = [];
176	  root.traverse((o) => { if ((o.isMesh || o.isSkinnedMesh) && !o.visible) drop.push(o); });
177	  for (const o of drop) o.parent.remove(o);
178	
179	  const bones = {};
180	  root.traverse((o) => { if (o.isBone) bones[o.name] = o; });
181	  const socket = root.getObjectByName('socket_weapon');
182	  const socketL = root.getObjectByName('socket_weapon_l');
183	
184	  let weapon = null, muzzleLocal = new THREE.Vector3(0, 0, 0.6);
185	  const offhandLocal = new THREE.Vector3();
186	  function setWeapon(model) {
187	    if (weapon) { weapon.parent?.remove(weapon); weapon = null; }
188	    if (!model || !socket) return;
189	    weapon = instantiate(model, matlib);
190	    socket.add(weapon);
191	    const m = model.anchors.muzzle;
192	    if (m) muzzleLocal.set(m[0], m[1], m[2]);
193	    const o = model.anchors.offhand;
194	    offhandLocal.set(o ? o[0] : 0, o ? o[1] : 0, o ? o[2] : 0.3);
195	  }
196	  setWeapon(weaponModel);
197	  // a grenade appears in the right hand while throwing; the rifle goes to the left
198	  const grenade = grenadeModel && socket ? instantiate(grenadeModel, matlib) : null;
199	  if (grenade) { grenade.visible = false; socket.add(grenade); }
200	  // a magazine or clip in the left hand while reloading

